      "summary": "Three concentric membranes that cover and protect the central nervous system: (1) Dura mater (the outer fibrous pachymeninge, comprising the falx cerebri in the interhemispheric fissure and the tentorium cerebelli), (2) Trabecular arachnoid membrane in the subarachnoid space filled with cerebrospinal fluid (CSF) and Pacchioni’s arachnoid granulations adjacent to the superior sagittal sinus, and (3) the inner vascular pia mater, which adheres to the cortical gyri and sulci.",
