      "functions": [
        "Supplies approximately 80 per cent of the total cerebral blood flow (approximately 750 mL/min at rest)",
        "Branches of the ophthalmic artery (supplying the retina and optic nerve) and the anterior choroidal artery (supplying the inner capsule and hippocampus)",
        "Connection to the posterior circulation via the posterior communicating artery"
      ],
      "citation": "Brott, T. G. et al. Stenting versus Endarterectomy for Treatment of Carotid-Artery Stenosis. N. Engl. J. Med. 363, 11–23 (2010).",
      "doi": "10.1056/NEJMoa0912321"
