      "badge": "AREE DI BRODMANN 3, 1 E 2 • OMUNCOLO SENSORIALE",
      "summary": "Fascia corticale granulare (coniocorteccia con strato IV iper-sviluppato) situata nel giro post-centrale, posteriormente al solco centrale di Rolando. Riceve le proiezioni talamiche dai nuclei VPL (corpo: colonne dorsali/lemnisco mediale e tratto spinotalamico) e VPM (faccia e cavità orale tramite il lemnisco trigeminale).",
